			break
		}
		var transientErr TransientError
		if errors.As(err, &transientErr) {
			// The resource is temporarily unavailable; retry.
			continue
		}
		return err
	}

	defer resource.Close()

	var frobErr error
	func() {
		defer func() {
			switch r := recover().(type) {
			case nil:
				// Frob succeeded.
			case FrobError:
				resource.Defrob(r.defrobTag)
				frobErr = r
			case *FrobError:
				resource.Defrob(r.defrobTag)
				frobErr = r
			case error:
				frobErr = r
			default:
				frobErr = fmt.Errorf("Frob panicked: %v", r)
			}
		}()
		resource.Frob(input)
	}()

	return frobErr
}
