package erratum

import (
	"errors"
	"fmt"
)

// Use opens a resource via opener, calls Frob(input) on it, and makes sure
// the resource is closed exactly once no matter what goes wrong.
//
// If the opener keeps failing with a TransientError, Use keeps retrying.
// Any other error from the opener is returned.
//
// If Frob panics with a FrobError, the resource's Defrob is called with the
// FrobError's defrobTag. In all cases where Frob panics, the recovered value
// is returned as an error.
func Use(opener ResourceOpener, input string) error {
	var resource Resource
	for {
		var err error
		resource, err = opener()
		if err == nil {
			break
		}
		var transientErr TransientError
		if errors.As(err, &transientErr) {
			// The resource is temporarily unavailable; try again.
			continue
		}
		return err
	}

	// The resource was opened successfully: it must be closed exactly once,
	// even if Frob panics below.
	defer resource.Close()

	var frobErr error
	func() {
		defer func() {
			switch r := recover().(type) {
			case nil:
				// Frob succeeded; nothing to do.
			case FrobError:
				resource.Defrob(r.defrobTag)
				frobErr = r
			case *FrobError:
				resource.Defrob(r.defrobTag)
				frobErr = r
			case error:
				frobErr = r
			default:
				frobErr = fmt.Errorf("Frob panicked: %v", r)
			}
		}()
		resource.Frob(input)
	}()

	return frobErr
}
